/**
 * @brief 在收到有效温度采样时确保对应 MCU 节点的在线版本状态已初始化
 * @param state 设备管理服务状态结构体指针
 * @param node 节点编号（1=MC，2=TH）
 * @param ts_ns 采样接收时间戳（纳秒）
 */
static void sync_version_on_sample(
    device_manager_state_t* state,
    uint8_t node,
    uint64_t ts_ns
) {
    if (state == nullptr || (node != 1U && node != 2U)) {
        return;
    }
    const char* node_str = (node == 1U) ? "MC" : "TH";
    aisoc_dev_mcu_version_t cur_ver;
    std::memset(&cur_ver, 0, sizeof(cur_ver));
    const aisoc_dev_status_t st = dev_state_get_mcu_version(state, node_str, &cur_ver);
    if (st == AISOC_DEV_OK && cur_ver.is_valid) {
        return;
    }
    aisoc_dev_mcu_version_t ver;
    populate_fallback_version(node, &ver);
    dev_state_update_mcu_version(state, node_str, &ver, ts_ns);
}

/**
 * @brief DDS 原始温度采样订阅回调：更新权威快照并向 DDS 与 D-Bus 广播更新事件
 * @param sample 接收到的原始温度采样只读指针
 * @param user_data 用户上下文指针（指向 device_manager_state_t）
 */
static void on_dds_raw_temp_cb(const aisoc_raw_temp_t* sample, void* user_data) {
    if (sample == nullptr || user_data == nullptr) {
        return;
    }
    device_manager_state_t* state = (device_manager_state_t*)user_data;
    aisoc_raw_temp_t rx_sample = *sample;
    const uint64_t rx_now_ns = get_host_monotonic_ns();
    if (rx_sample.host_received_ns > 0U && rx_now_ns > rx_sample.host_received_ns &&
        (rx_now_ns - rx_sample.host_received_ns) < 30000000000ULL) {
        rx_sample.host_received_ns = rx_now_ns;
    }

    pthread_mutex_lock(&state->state_mutex);
    if (is_sample_valid(&rx_sample)) {
        sync_version_on_sample(state, rx_sample.source_node, rx_sample.host_received_ns);
    }
    dev_state_update_raw_sample(state, &rx_sample);

    if (state->dds_pub_snapshot != nullptr) {
        aisoc_dds_publish_temp_snapshot(state->dds_pub_snapshot, &state->snapshot);
    }
    const uint32_t gen_id = state->snapshot.generation_id;
    const uint64_t ts_ns = state->snapshot.timestamp_ns;
    dev_dbus_emit_snapshot_updated(state, gen_id, ts_ns);
    pthread_mutex_unlock(&state->state_mutex);

    std::printf("[DEVICE_MGR DEBUG] DDS RX: node=%u, temp=%d millic (%.1f C) -> Snapshot GEN=%u (%s)\n",
                rx_sample.source_node, rx_sample.temperature_millic,
                (double)rx_sample.temperature_millic / 1000.0,
                gen_id, state->snapshot.system_status_desc);
    std::fflush(stdout);
}

